oxy_webhelp_navlinks = {"recover_oracle_databases-d39536e39145":{"topics":[{"title":"Point-in-time recovery","shortdesc":"<p class=\"shortdesc\">Point-in-time recovery uses database snapshots and their associated logs to restore a     database to its state at a specific point in time.<\/p>","href":"oracle\/point-in-time_recovery.html","attributes":{"data-id":"point-in-time_recovery"},"menu":{"hasChildren":false},"tocID":"point-in-time_recovery-d39536e39159","topics":[]},{"title":"Validating Oracle database snapshots","shortdesc":"<p class=\"shortdesc\">Validate the data in an Oracle database snapshot to confirm that there are no corrupt         files or missing blocks before you recover or restore the database.<\/p>","href":"oracle\/rbk_validating_oracle_database_snapshots.html","attributes":{"data-id":"rbk_validating_oracle_database_snapshots"},"menu":{"hasChildren":false},"tocID":"rbk_validating_oracle_database_snapshots-d39536e39170","topics":[]},{"title":"Database clones for Oracle","shortdesc":"<p class=\"shortdesc\">You can clone an Oracle database to a target location by selecting a recovery     point.<\/p>","href":"oracle\/about_db_clones.html","attributes":{"data-id":"about_db_clones"},"menu":{"hasChildren":false},"tocID":"about_db_clones-d39536e39181","next":"about_db_clones-d39536e39181"},{"title":"Oracle Live Mount","shortdesc":"<p class=\"shortdesc\">An Oracle Live Mount creates a database from a point-in-time copy of the source     database to reduce the recovery time.<\/p>","href":"oracle\/oracle_live_mount.html","attributes":{"data-id":"oracle_live_mount"},"menu":{"hasChildren":false},"tocID":"oracle_live_mount-d39536e39247","next":"oracle_live_mount-d39536e39247"},{"title":"Clone and Live Mount recovery customization","shortdesc":"<p class=\"shortdesc\">You can customize clone or live mount recoveries by specifying your own         initialization parameter values.<\/p>","href":"oracle\/clone_lm_recovery_customization.html","attributes":{"data-id":"clone_lm_recovery_customization"},"menu":{"hasChildren":false},"tocID":"clone_lm_recovery_customization-d39536e39409","next":"clone_lm_recovery_customization-d39536e39409"},{"title":"Instant Recovery for Oracle","shortdesc":"<p class=\"shortdesc\">Instant Recovery for Oracle replaces an existing database with a point-in-time copy,     requiring specific configurations and directory setup.<\/p>","href":"oracle\/oracle_instant_recovery.html","attributes":{"data-id":"oracle_instant_recovery"},"menu":{"hasChildren":false},"tocID":"oracle_instant_recovery-d39536e39464","next":"oracle_instant_recovery-d39536e39464"},{"title":"Same Host Recovery","shortdesc":"<p class=\"shortdesc\">Recover a database to the source Oracle host or Oracle RAC.<\/p>","href":"oracle\/samehost_recover.html","attributes":{"data-id":"about_samehost_recover"},"menu":{"hasChildren":false},"tocID":"about_samehost_recover-d39536e39500","next":"about_samehost_recover-d39536e39500"},{"title":"Downloading an archived Oracle database snapshot","shortdesc":"<p class=\"shortdesc\">Recover an Oracle database snapshot that is no longer stored on the local cluster but         remains available in an archival location.<\/p>","href":"oracle\/downloading_archived_oracle_db_snapshot.html","attributes":{"data-id":"downloading_archived_oracle_db_snapshot"},"menu":{"hasChildren":false},"tocID":"downloading_archived_oracle_db_snapshot-d39536e39544","topics":[]},{"title":"Recovering an Oracle database from a replica","shortdesc":"<p class=\"shortdesc\">Recover an Oracle database from a replicated snapshot of the database stored on         another Rubrik cluster.<\/p>","href":"oracle\/recovering_oracle_database_replica.html","attributes":{"data-id":"recovering_oracle_database_replica"},"menu":{"hasChildren":false},"tocID":"recovering_oracle_database_replica-d39536e39555","topics":[]},{"title":"Recovery from RAC to standalone Oracle hosts","shortdesc":"<p class=\"shortdesc\">You can use the Live Mount or Clone recovery methods to recover a database snapshot         that was originally hosted on an Oracle RAC to an Oracle standalone host.<\/p>","href":"oracle\/recovery_rac_standalone_oracle_hosts.html","attributes":{"data-id":"recovery_rac_standalone_oracle_hosts"},"menu":{"hasChildren":false},"tocID":"recovery_rac_standalone_oracle_hosts-d39536e39566","topics":[]},{"title":"Recovery to a secondary Oracle host","shortdesc":"<p class=\"shortdesc\">You can add a secondary Oracle host to a Rubrik cluster to provide more target options     for snapshot recovery.<\/p>","href":"oracle\/recovery_secondary_oracle_host.html","attributes":{"data-id":"recovery_secondary_oracle_host"},"menu":{"hasChildren":false},"tocID":"recovery_secondary_oracle_host-d39536e39578","topics":[]},{"title":"Oracle recovery using SCNs","shortdesc":"<p class=\"shortdesc\">You can recover Oracle snapshots and mount archive logs using the system change         number instead of the date and time when the snapshot occurs, providing a more accurate         point of recovery.<\/p>","href":"oracle\/oracle_recovery_using_scns.html","attributes":{"data-id":"oracle_recovery_using_scns"},"menu":{"hasChildren":false},"tocID":"oracle_recovery_using_scns-d39536e39589","next":"oracle_recovery_using_scns-d39536e39589"},{"title":"Tablespace recovery","shortdesc":"<p class=\"shortdesc\">Restore a tablespace in place to the same database.<\/p>","href":"oracle\/tablespace_recovery.html","attributes":{"data-id":"tablespace_recovery"},"menu":{"hasChildren":false},"tocID":"tablespace_recovery-d39536e39644","next":"tablespace_recovery-d39536e39644"},{"title":"Bigfile tablespace restore for Oracle databases","shortdesc":"<p class=\"shortdesc\">The Rubrik cluster supports restoring Oracle databases that are configured for         bigfile tablespaces, which create very large data or temporary files.<\/p>","href":"oracle\/bigfile_tablespace_restore_for_orcl_dbs.html","attributes":{"data-id":"bigfile_tablespace_restore_for_orcl_dbs"},"menu":{"hasChildren":false},"tocID":"bigfile_tablespace_restore_for_orcl_dbs-d39536e39677","topics":[]},{"title":"Oracle 26ai database recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports protection of Oracle 26ai and Oracle 23ai databases         running on Oracle Exadata on-premises. The following known issues might affect recovery         operations.<\/p>","href":"oracle\/oracle_26ai_database_protection.html","attributes":{"data-id":"oracle_26ai_database_protection"},"menu":{"hasChildren":false},"tocID":"oracle_26ai_database_protection-d39536e39688","topics":[]},{"title":"Oracle ExaCS database recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports protection of Oracle Exadata Cloud Service databases.         The following known issues might affect recovery operations.<\/p>","href":"oracle\/oracle_exacs_database_protection.html","attributes":{"data-id":"oracle_exacs_database_protection"},"menu":{"hasChildren":false},"tocID":"oracle_exacs_database_protection-d39536e39701","topics":[]},{"title":"Oracle Exadata Exascale database recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports recovery of Oracle Exadata Exascale databases. The         following known issues might affect recovery operations.<\/p>","href":"oracle\/oracle_exadata_exascale_db_protection.html","attributes":{"data-id":"oracle_exadata_exascale_db_protection"},"menu":{"hasChildren":false},"tocID":"oracle_exadata_exascale_db_protection-d39536e39714","topics":[]},{"title":"Policy-managed database recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects both policy-managed databases and admin-managed         databases.<\/p>","href":"oracle\/policy_managed_database_recovery.html","attributes":{"data-id":"policy_managed_database_recovery"},"menu":{"hasChildren":false},"tocID":"policy_managed_database_recovery-d39536e39727","topics":[]},{"title":"Recovery chains","shortdesc":"<p class=\"shortdesc\">Converting a backed-up database to a different Oracle database format breaks the         recovery chain after a host refresh.<\/p>","href":"oracle\/recovery_chains.html","attributes":{"data-id":"recovery_chains"},"menu":{"hasChildren":false},"tocID":"recovery_chains-d39536e39740","topics":[]},{"title":"Number of channels in recovery","shortdesc":"<p class=\"shortdesc\">The number of RMAN channels RMAN uses during a recovery controls the number of         concurrent streams that can process data.<\/p>","href":"oracle\/number_of_channels_in_recovery.html","attributes":{"data-id":"number_of_channels_in_recovery"},"menu":{"hasChildren":false},"tocID":"number_of_channels_in_recovery-d39536e39751","topics":[]},{"title":"Export Oracle database logs to a USB device","shortdesc":"<p class=\"shortdesc\">You can use Rubrik REST APIs to export logs from multiple Oracle databases to USB         devices.<\/p>","href":"oracle\/export_database_logs_usb.html","attributes":{"data-id":"export_database_logs_usb"},"menu":{"hasChildren":false},"tocID":"export_database_logs_usb-d39536e39762","next":"export_database_logs_usb-d39536e39762"},{"title":"Archived log restore","shortdesc":"<p class=\"shortdesc\">Archived log restore reinstates archived logs from a specified time range or SCN         range.<\/p>","href":"oracle\/archived_log_restore.html","attributes":{"data-id":"archived_log_restore"},"menu":{"hasChildren":false},"tocID":"archived_log_restore-d39536e39818","next":"archived_log_restore-d39536e39818"}]}};